const body = $json.body;

// Chatwoot sends two different payload shapes depending on delivery path:
// - Account-level webhook (event "message_created"): flat, message fields
//   directly on body (body.content, body.message_type as a string).
// - Automation-rule webhook (event "automation_event.message_created"):
//   body IS the conversation object; the actual message is the last item
//   in body.messages, and message_type is numeric (0 = incoming, 1 = outgoing).
const isAutomationEvent = (body.event || '').startsWith('automation_event.');

let message, inboxId, inboxTitle, convId, channelType, accountId, accountName;

if (isAutomationEvent) {
  message = (body.messages && body.messages[body.messages.length - 1]) || {};
  inboxId = body.inbox_id;
  inboxTitle = undefined;
  convId = body.id;
  channelType = body.channel;
  accountId = body.account && body.account.id;
  accountName = body.account && body.account.name;
} else {
  message = body;
  inboxId = body.inbox && body.inbox.id;
  inboxTitle = body.inbox && body.inbox.name;
  convId = body.conversation && body.conversation.id;
  channelType = body.conversation && body.conversation.channel;
  accountId = body.account && body.account.id;
  accountName = body.account && body.account.name;
}

const rawMessageType = message.message_type;
const messageType =
  rawMessageType === 0 || rawMessageType === 'incoming' ? 'incoming' :
  rawMessageType === 1 || rawMessageType === 'outgoing' ? 'outgoing' :
  String(rawMessageType);

const conversation = isAutomationEvent ? body : body.conversation;

return [{
  json: {
    data: {
      inbox_id: inboxId !== undefined ? String(inboxId) : 'undefined',
      inbox_title: inboxTitle !== undefined ? String(inboxTitle) : 'undefined',
      conv_id: convId !== undefined ? String(convId) : 'undefined',
      channel_type: channelType !== undefined ? String(channelType) : 'undefined',
      message_id: message.id !== undefined ? String(message.id) : 'undefined',
      message_content: message.content !== undefined ? message.content : 'undefined',
      message_type: messageType,
      private: message.private !== undefined ? String(message.private) : 'undefined',
      account_id: accountId !== undefined ? String(accountId) : 'undefined',
      account_name: accountName !== undefined ? String(accountName) : 'undefined',
      content_type: message.content_type !== undefined ? String(message.content_type) : 'undefined',
      created_at: message.created_at !== undefined ? String(message.created_at) : 'undefined',
      event: body.event,
      conversation_labels: (conversation && conversation.labels) || [],
      attachments: body.attachments || [],
      meta: (conversation && conversation.meta) || null,
    },
  },
}];
